    """Tokenizer for numeric types with precision handling."""

    def __init__(
        self,
        precision: int = 6,
        # DANGER: Mutable default argument - Python allows, Scala doesn't
        format_options: dict[str, Any] = {},  # noqa: B006
    ) -> None:
        self.precision = precision
