// Token Types
// ============================================================================

sealed abstract class TokenType(val value: String)

object TokenType {
  case object STRING extends TokenType("string")
  case object NUMERIC extends TokenType("numeric")
  case object TEMPORAL extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY extends TokenType("binary")
  case object NULL extends TokenType("null")

  val values: Vector[TokenType] = Vector(STRING, NUMERIC, TEMPORAL, STRUCTURED, BINARY, NULL)
}

// ============================================================================
// Core Token Classes
// ============================================================================

final case class Token(value: String, tokenType: TokenType, metadata: Map[String, Any] = Map.empty) {
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)

  def withMetadata(extra: Map[String, Any]): Token =
    copy(metadata = metadata ++ extra)
}

final class MutableTokenBatch {
  private val buffer = mutable.ListBuffer.empty[Token]
  private var processed = false

  def add(token: Token): Unit = {
    if (processed) throw new IllegalStateException("Batch already processed")
    buffer += token
  }

  def markProcessed(): Unit = {
    processed = true
  }

  def tokens: Vector[Token] = buffer.toVector
}

// ============================================================================
// Generic Container Classes
// ============================================================================

final class TokenContainer[+T](items: Seq[T]) {
  private val allItems: Vector[T] = items.toVector

  def getAll: Vector[T] = allItems

  def mapTokens(func: T => String): List[String] = allItems.map(func).toList

  def size: Int = allItems.size
}

final class TokenSink[-T] {
  private val received = mutable.ListBuffer.empty[Any]

  def receive(item: T): Unit = {
    received += item
  }

  def drain(): List[Any] = {
    val out = received.toList
    received.clear()
    out
  }
}

final class BivariantHandler[T](default: T) {
  private var value: T = default

  def get: T = value

  def set(next: T): Unit = {
    value = next
  }

  def transform(func: T => T): T = {
    value = func(value)
    value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

final class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Any] {

  private val charset = Charset.forName(encoding)

  def tokenize(value: Any): Token = {
    val strValue = value match {
      case bytes: Array[Byte] => new String(bytes, charset)
      case str: String => str
      case other => other.toString
    }

    Token(normalizer(strValue), TokenType.STRING)
  }
}

final class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {

  private def formatDecimal(value: BigDecimal): String = {
    val scaled = value.setScale(precision, BigDecimal.RoundingMode.HALF_UP)
    f"$scaled%1.${precision}f"
  }

  private def formatDouble(value: Double): String =
    String.format(Locale.ROOT, s"%.${precision}f", Double.box(value))

  def tokenize(value: Any): Token = {
    val strValue = value match {
      case bd: BigDecimal => formatDecimal(bd)
      case jd: JBigDecimal => formatDecimal(BigDecimal(jd))
      case d: Double => formatDouble(d)
      case f: Float => formatDouble(f.toDouble)
      case i: Byte => i.toString
      case i: Short => i.toString
      case i: Int => i.toString
      case i: Long => i.toString
      case other => other.toString
    }

    val meta = Map("original_type" -> value.getClass.getSimpleName) ++ formatOptions
    Token(strValue, TokenType.NUMERIC, meta)
