final class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  val ISO_FORMAT: String = "yyyy-MM-dd'T'HH:mm:ss"
  val DATE_FORMAT: String = "yyyy-MM-dd"

  def tokenize(value: Any): Token = {
    val formatter = formatStr
      .map(DateTimeFormatter.ofPattern)
      .getOrElse {
        value match {
          case _: LocalDateTime => DateTimeFormatter.ofPattern(ISO_FORMAT)
          case _: LocalDate => DateTimeFormatter.ofPattern(DATE_FORMAT)
          case _ => DateTimeFormatter.ofPattern(ISO_FORMAT)
        }
