        results += matched
      }
      results.toList
    }.getOrElse(List.empty)
  }
}

// ============================================================================
// Functor / Monad Simulation
// ============================================================================

class TokenFunctor[T](protected val value: T) {
  def map[U](func: T => U): TokenFunctor[U] = new TokenFunctor(func(value))

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = func(value)

  def getOrElse(default: T): T = if (value != null) value else default

  def get: T = value
}

final class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] =
    new TokenMonad(funcWrapped.value(value))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

final class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] = {
    val parts = path.split("\\.").toList.filter(_.nonEmpty)

    def descend(current: Json, remaining: List[String]): Option[Json] = remaining match {
      case Nil => Some(current)
      case head :: tail =>
        if (current.isObject) {
          current.asObject.flatMap(_.apply(head)).flatMap(descend(_, tail))
        } else if (current.isArray && head.forall(_.isDigit)) {
          val idx = head.toInt
          val arr = current.asArray.getOrElse(Vector.empty)
          if (idx >= 0 && idx < arr.size) descend(arr(idx), tail) else None
        } else {
          None
        }
    }

    descend(value, parts).map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer
// ============================================================================

final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def trimPunctuation(word: String): String = {
    val start = word.dropWhile(punctuation.contains)
    start.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) trimPunctuation(word) else word
    val normalized = if (lowercase) stripped.toLowerCase(Locale.ROOT) else stripped

    if (normalized.length < minLength) return None

    val truncated = maxLength match {
      case Some(max) if normalized.length > max => normalized.take(max)
      case _ => normalized
    }

    if (truncated.nonEmpty) Some(truncated) else None
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val tokens = mutable.ListBuffer.empty[Token]

    for ((word, idx) <- words.zipWithIndex) {
      processToken(word).foreach { processed =>
        tokens += Token(processed, TokenType.STRING, Map("position" -> idx, "original" -> word))
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    val results = mutable.ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    for (word <- words) {
      val start = text.indexOf(word, currentPos)
      val safeStart = if (start >= 0) start else currentPos
      val end = safeStart + word.length

      processToken(word).foreach { processed =>
        results += ((processed, safeStart, end))
      }

      currentPos = end
    }

    results.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final class TokenizerBuilder[T] private () {
  private val normalizers = mutable.ListBuffer.empty[String => String]
  private val validators = mutable.ListBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= entries.toMap
    this
  }

  def build(): T => Token = {
    val activeNormalizers = normalizers.toList
    val activeValidators = validators.toList
    val activeMetadata = metadata.toMap

    (value: T) => {
      activeValidators.foreach { validator =>
        if (!validator(value)) throw new IllegalArgumentException(s"Validation failed for $value")
      }

      var strValue = value.toString
      activeNormalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }

      Token(strValue, TokenType.STRING, activeMetadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
